entries[208940] = { ["name"] = "Voidsong, Stave of the Harbinger", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Staff\n1 - 2 Damage Speed 3.60\n(0.4 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n\"A gift of Dimensius bestowed at the height of the Black Empire. Those touched by shadow are drawn to its haunting whispers.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208941] = { ["name"] = "M'thorus, Dagger of the Grand Design", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Dagger\n1 Damage Speed 1.80\n(0.6 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n\"Shadows cannot be allowed to fester. Disorder must be struck down wherever it takes hold. True children of the titans will heed their makers' call.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208942] = { ["name"] = "Preservationist's Dispatch Three", ["text"] = "Secrets of Azeroth\nBinds when picked up\n\"A note describing an orb artifact that the Preservationists need to be collected.\"\n<Right Click to Read>" }
entries[208943] = { ["name"] = "Arsenal: Cosmic Weapons Cache", ["text"] = "Binds to Warband\nUse: Collect the appearances contained in the Cosmic Weapons Cache.\n\"Armaments forged from the primal fabric of the cosmos. Who assembled this collection and why remains a mystery. Wielding them will draw the eye of those who covet such power.\"" }
entries[208944] = { ["name"] = "Orb of Rathmus", ["text"] = "Secrets of Azeroth\nBinds when picked up\nThis Item Begins a Quest\n\"Titan script adorns the metal bands encircling the glowing orb.\"" }
entries[208945] = { ["name"] = "Paracausal Crate", ["text"] = "Binds to Warband\nUse: Open to gain 500 Paracausal Flakes.\n\"Unfortunately, for the health of the timeline, it is recomended this be opened after being sent.\"" }
entries[208946] = { ["name"] = "Burning Rune", ["text"] = "Quest Item\n\"A mysterious etching that emanates an uncomfortable heat.\"" }
entries[208947] = { ["name"] = "Enchanted Watering Can", ["text"] = "Quest Item\nUnique\nUse: Sprinkle water upon enchanted shrubs, giving them the energy to deliver themselves to Magnolia Oaken.\n\"More powerful than an average watering can.\"" }
entries[208949] = { ["name"] = "Heated Hearthstone", ["text"] = "Quest Item\n\"Warm and inviting, great for heating up hands.\"" }
entries[208950] = { ["name"] = "Emerald Fiber", ["text"] = "Quest Item\n\"A hearty fiber that possesses remarkable tensile strength.\"" }
entries[208951] = { ["name"] = "Paracausal Cluster", ["text"] = "Binds to Warband\nUse: Crush to gain 1000 Paracausal Flakes.\n\"A crystal formation emerging just before the collision of two timeways, made of compressed sands of time.\"" }
entries[208952] = { ["name"] = "Soridormi's Letter of Commendation", ["text"] = "Binds to Warband\nUse: Read to gain 1000 reputation with Soridormi.\n\"A letter of recognition signed by Soridormi.\"" }
entries[208955] = { ["name"] = "Pilfered Dreamshard", ["text"] = "Quest Item" }
entries[208956] = { ["name"] = "Intact Primalist Garb", ["text"] = "Quest Item\n\"It is a good thing blood on the clothes was optional. It may have taken a very long time otherwise.\"" }
entries[208957] = { ["name"] = "Conduit of the Southern Storm", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"This ancient obelisk looks to have been carved from a piece of electrically charged glass or crystal.\"" }
entries[208958] = { ["name"] = "Ancient Tyrhold Artifact Notes", ["text"] = "Secrets of Azeroth\nBinds when picked up\n\"Contains notes written by Kathos and Bobby regarding the artifact's safeguards at Tyrhold.\"\n<Right Click to Read>" }
entries[208959] = { ["name"] = "Taesavir, Sword of the Grand Design", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n\"An edge so sharp it could only be honed by Aggramar himself. Any who defy the will of the titans should beware its wielder.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208960] = { ["name"] = "Titan Focusing Crystal", ["text"] = "Secrets of Azeroth\nBinds when picked up\n\"This is clearly one of the objects that was shattered and is needed for the second set of artifact locks.\"" }
entries[208962] = { ["name"] = "Seetheras, Broadsword of the Sunderer", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Sword\n1 - 2 Damage Speed 3.60\n(0.4 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n\"Forged from malignant chaos to strike at the target's heart. Those whose souls burn with all-consuming rage are drawn to its dark fire.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
