entries[208980] = { ["name"] = "Cache of Cosmic Curiosities", ["text"] = "Secrets of Azeroth\nQuest Item\n\"Languages associated with order, fel, and void are engraved on the surface of the chest. It is magically sealed, without a single seam or hinge.\"" }
