entries[208984] = { ["name"] = "First Booster Part", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUse: Combine the first, second, and third boosters near an Empowered Arcane Forge to reforge and power Mimiron's Jumpjets." }
entries[208985] = { ["name"] = "Silly Hat", ["text"] = "Quest Item\nUse: Stealthily slip a silly hat onto a sleeping druid.\n\"A fun party hat brought to the Emerald Dream by Lady Moonberry for the purpose of hatting druids.\"" }
