entries[209017] = { ["name"] = "Teleportal Creator", ["text"] = "Quest Item\nUse: Creates an experimental Teleportal allowing you to travel to locations within the dream containing Research Beacons. (15 Sec Cooldown)\n\"Engineering portal creator.\"" }
entries[209018] = { ["name"] = "Glowdrop Sugar", ["text"] = "Quest Item\n\"Soft, airy pollen collected from Shaded Glowdrops. Intensely sweet smelling, vanilla forward, with a hint of cinnamon, hence the name. However, it is exceedingly unsafe to ingest.\"" }
entries[209019] = { ["name"] = "Conjured Sugarfree Firewater Sorbet", ["text"] = "Conjured Item\nUnique: Conjured Dessert (1)\nUse: Increases your size.\nSell Price:" }
entries[209021] = { ["name"] = "Shed Great Feathers", ["text"] = "Quest Item\n\"Long, soft feathers shed from a great somnowl.\"" }
entries[209024] = { ["name"] = "Loot-Filled Pumpkin", ["text"] = "Binds when picked up\nRequires Hallow's End\n<Right Click to Open>" }
entries[209026] = { ["name"] = "Loot-Stuffed Pumpkin", ["text"] = "Binds when picked up\nRequires Hallow's End\n<Right Click to Open>" }
entries[209033] = { ["name"] = "Worn Felsteel Prayer Rod", ["text"] = "\"Etched into the rod are the words 'His might is our faith. His word is our might. His will is the rebirth of the Burning Crusade.'\"\nSell Price:" }
entries[209034] = { ["name"] = "Half-Completed Invasion Plans", ["text"] = "\"Incomplete plans for a new Legion invasion of a distant world you've never heard of.\"\nSell Price:" }
entries[209035] = { ["name"] = "Hearthstone of the Flame", ["text"] = "Binds when picked up\nToy\nUse: Returns you to Hearthstone Location. Speak to an Innkeeper in a different place to change your home location.\n\"Home is where your flame burns brightest.\"" }
entries[209036] = { ["name"] = "Cache of Amirdrassil Treasures", ["text"] = "Binds when picked up\n\"Rewards a piece of equipment for your Loot Specialization.\"\n<Right Click to Open>" }
entries[209037] = { ["name"] = "Cache of Amirdrassil Treasures", ["text"] = "Heroic\nBinds when picked up\n\"Rewards a piece of equipment for your Loot Specialization.\"\n<Right Click to Open>" }
entries[209038] = { ["name"] = "Tyr's Titan Key", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Polearm\n1 - 3 Damage Speed 3.60\n(0.6 damage per second)\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[209039] = { ["name"] = "Tyr's Titan Key", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Mace\n1 Damage Speed 2.60\n(0.4 damage per second)\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[209040] = { ["name"] = "Tyr's Titan Key", ["text"] = "Cosmetic\nBinds to Warband\nHeld In Off-hand\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[209044] = { ["name"] = "Orange Brewfest Bulwark", ["text"] = "Cosmetic\nBinds to Warband\nOff Hand Shield\n14 Armor\nDurability 30 / 30\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[209048] = { ["name"] = "Singed Leaflet", ["text"] = "Quest Item\n\"Parchment smelling strongly of sulfur and ash, covered in scrawled writings and smudged charcoal.\"" }
entries[209049] = { ["name"] = "Essence of Endless Flame", ["text"] = "Quest Item\n\"The tiny shard looks fragile but ever bright. It is not too hot to touch, but its warmth fades.\"" }
entries[209050] = { ["name"] = "Somnium Bark", ["text"] = "Quest Item\nUnique\nRequires level 10 to 80 ( 80)\n\"The bark of the Somnium tree can be used as a remedy for many ailments.\"" }
entries[209051] = { ["name"] = "Sleeping Glory", ["text"] = "Quest Item\nUnique\nRequires level 10 to 80 ( 80)\n\"These orange-yellow flowers are said to manifest and bloom after a druid had a long and fulfilling sleep. They resemble the rising sun and used metaphorically as a sunrise or a new beginning.\"" }
entries[209052] = { ["name"] = "Brew Barrel", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Summon and ride a rolling barrel for 30 sec. (10 Min Cooldown)" }
entries[209053] = { ["name"] = "Green Brewfest Bulwark", ["text"] = "Cosmetic\nBinds to Warband\nOff Hand Shield\n14 Armor\n\"Smells like Brewfest.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[209054] = { ["name"] = "Ritual Remedy", ["text"] = "Quest Item\nUnique\nRequires level 10 to 80 ( 80)\n\"This ritualistic remedy is said to break the bond between a living creature and dream spirit.\"" }
entries[209055] = { ["name"] = "Third Booster Part", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUse: Combine the first, second, and third boosters near an Empowered Arcane Forge to reforge and power Mimiron's Jumpjets." }
entries[209060] = { ["name"] = "Verdant Armoredon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The gnarled horns of this armoredon are far stronger than bone.\"\nAchievement:\nDragonflight Keystone Master: Season Three\nCategory:\nDungeons" }
entries[209061] = { ["name"] = "Ishtaar Rethon's Burial Banner", ["text"] = "Secrets of Azeroth\nBinds when picked up\n\"The text on the banner depicts the pilgrimage of Ishtaar Rethon. Jhara at Pinewood Post knows where to start.\"" }
