entries[209343] = { ["name"] = "Verdant Gladiator's Badge of Ferocity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 634 Critical Strike\nUse: Increases primary stat by 1595 for 15 sec. (1 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[209344] = { ["name"] = "Verdant Gladiator's Insignia of Alacrity", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 634 Haste\nEquip: Your spells and abilities have a chance to grant 1346 primary stat for 20 sec.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[209345] = { ["name"] = "Verdant Gladiator's Emblem", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+603 [Agility or Strength or Intellect]\nUse: Increases maximum health by 177846 for 15 sec. (2 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[209346] = { ["name"] = "Verdant Gladiator's Medallion", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+603 [Agility or Strength or Intellect]\nUse: Removes all movement impairing effects and all effects which cause loss of control of your character.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[209347] = { ["name"] = "Verdant Gladiator's Sigil of Adaptation", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+603 [Agility or Strength or Intellect]\nEquip: Removes any loss of control effect with a duration of 5 seconds or more. This effect can only occur once every 1 min.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
