entries[209947] = { ["name"] = "Reins of the Blossoming Dreamstag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n\"The pelts of young dreamstags flower with the vibrant colors of the dream.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1" }
entries[209948] = { ["name"] = "Spring's Keeper", ["text"] = "Binds when picked up\nTwo-Hand Polearm\n1,007 - 1,872 Damage Speed 3.60\n(399.9 damage per second)\n+531 Strength\n+1,759 Stamina\n+ 283 Haste\n+ 525 Mastery\nDurability 120 / 120\nUse: Transforms Spring's Keeper into Winter's Stand.\nEquip: Autoattacks have a chance to heal a nearby ally for 24357 .\nSell Price:" }
entries[209949] = { ["name"] = "Reins of the Suntouched Dreamstag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Dream Wardens.\nSell Price:\n\"The sun's radiant energy nurtures these dreamstags, helping them rapidly reach maturity.\"\nVendor:\nMoon Priestess Lasara\nZone:\nEmerald Dream\nCost:\n1200" }
entries[209950] = { ["name"] = "Reins of the Rekindled Dreamstag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n\"Ashes of fallen leaves are fertile soil for dreamstags to arise from.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1" }
entries[209951] = { ["name"] = "Reins of the Lunar Dreamstag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Dream Wardens.\nSell Price:\n\"The moon's pale light is reflected in the pelt of these elusive nocturnal creatures.\"\nVendor:\nMoon Priestess Lasara\nZone:\nEmerald Dream\nCost:\n1200" }
entries[209952] = { ["name"] = "Mark of Q'onzu", ["text"] = "Quest Item\nUse: Show the Cinder Flamekin Q'onzu's feather to prove your loyalty. (5 Sec Cooldown)" }
entries[209953] = { ["name"] = "Dancing Dream Blossoms", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+505 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to grant 1892 secondary stats the way you like them!\nSell Price:" }
entries[209954] = { ["name"] = "Moragh's Favorite Rock", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+505 Strength\nEquip: Your melee attacks have a chance to deal 69033 Nature damage split between the target and nearby enemies.\n\nDamage is increased for each enemy struck, up to 5 enemies.\nSell Price:" }
entries[209955] = { ["name"] = "Root of Fire", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+ 577 Critical Strike\nEquip: Taking damage and melee attacks can coat yourself in fiery thorns, granting 1726 Strength and reducing damage taken from enemies by 1175 for 9 sec.\nSell Price:" }
entries[209956] = { ["name"] = "Ori's Verdant Feather", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+ 577 Haste\nEquip: Damaging spells and abilities have a chance to grant 1515 Agility and 457 Speed for 7 sec.\nSell Price:" }
entries[209957] = { ["name"] = "Fang of the Frenzied Nightclaw", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+505 Agility\nEquip: Damaging spells and abilities have a chance to call a Nightclaw to eviscerate the target, dealing 59171 Physical damage and an additional ( 8284 * 5) Physical damage over 5 sec.\nSell Price:" }
entries[209958] = { ["name"] = "Rune of the Umbramane", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+505 Intellect\nEquip: Spells and abilities have a chance to bathe the target in moonlight, dealing 41419 Arcane damage to an enemy or restoring 62172 health to an ally.\nSell Price:" }
entries[209959] = { ["name"] = "Pinch of Dream Magic", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+ 577 Mastery\nEquip: Spells and abilities have a chance to grant 1645 Intellect and shapeshift you. (10s cooldown)\nSell Price:" }
