entries[209996] = { ["name"] = "Tethercoil Rune", ["text"] = "Binds when picked up\nUse: Inflict Tethercoil Siphon to yourself by binding to any Rare creature in the Emerald Dream.\n\nDefeating Rare creatures while Tethercoil Siphon is active will earn Taut Tethercoil. (5 Sec Cooldown)\n\"Lydiara's rune to siphon Taut Tethercoil from powerful creatures throughout the Emerald Dream.\"" }
entries[209997] = { ["name"] = "Distilled Knowledge of Timeways", ["text"] = "Binds to Warband\nUnique (5)\nUse: Increases experience gained from killing monsters and completing quests by 5%.\n\nCompleting Timewalking dungeons increases the effect and refreshes the duration.\n\nUpon reaching 4 applications, transforms to Mastery of Timeways , increasing that effect to 30%." }
entries[209998] = { ["name"] = "Lydiara's Binding Rune", ["text"] = "Binds when picked up\n\"Crafted in tandem with Lydiara Whisperfeather.\"" }
entries[209999] = { ["name"] = "Lydiara's Rune of Shadowbinding", ["text"] = "Binds when picked up\nUse: Tether yourself to Gnarlroot, Igira, or Volcoross, becoming Shadowbound.\n\nWhile Shadowbound you will be afflicted with Roaring Shadowflame, slowing you between 0-50% based on the distance from your target and has a chance to hinder your mobility every 5 sec. (5 Sec Cooldown)\n\"A Rune of Shadowbinding ready for attunement with Fyr'alath.\"" }
entries[210001] = { ["name"] = "Prototype Order Vellum", ["text"] = "Binds when picked up\n\"A prototype vellum made by Shalasar from flecks of radiant ash.\"" }
entries[210002] = { ["name"] = "Ashen Dowsing Rod", ["text"] = "Quest Item\nUse: Extracts Radiant Fleck of Ash from powerful (EPIC) quality weapons or armor. The targeted item will be DESTROYED and will not be retrievable. (5 Min Cooldown)\n\"A dowsing rod that allows the user the ability to disenchant powerful pieces of equipment in order to find Radiant Fleck of Ash.\"" }
entries[210003] = { ["name"] = "Shalasar's Sophic Vellum", ["text"] = "Binds when picked up\n\"Crafted in tandem with Shalasar Glimmerdusk.\"" }
entries[210005] = { ["name"] = "10.2 Monster - Weapon - Staff - 10.1.5 Weapon Staff - Staff_2H_Druid_C_02_Color1", ["text"] = "Binds when equipped\nTwo-Hand Staff\n7 - 10 Damage Speed 3.60\n(2.4 damage per second)\n+28 Intellect\n+9 Stamina\n+ 8 Critical Strike\n+ 5 Haste\nSell Price:" }
entries[210008] = { ["name"] = "Smoldering Rune of Binding", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"By fire be purged the obstacles in your path!\"\nPromotion:\nCataclysm Classic" }
entries[210009] = { ["name"] = "Prototype Dreamleaf Grip", ["text"] = "Binds when picked up\n\"A prototype rune made by Erden from leathery Shadowed Dreamleaf.\"" }
entries[210010] = { ["name"] = "Erden's Notes on Symbiotic Spores", ["text"] = "Binds when picked up\nUse: Share Erden's notes with a friendly Leatherworker and temporarily teach them how to craft Erden's Dreamleaf Grip. Leatherworker must be in the same party. (30 Min Cooldown)\n\"Notes detailing the necessities to craft an experimental Symbiotic Glowspore Grip. Written by Master Leatherworker Erden.\"" }
entries[210011] = { ["name"] = "Shalasar's Notes on Sophic Magic", ["text"] = "Binds when picked up\nUse: Share Shalasar's notes with a friendly Enchanter and temporarily teach them how to craft Shalasar's Sophic Vellum. Enchanter must be in the same party. (30 Min Cooldown)\n\"Notes detailing the necessities to craft an experimental Sophic Vellum. Written by Master Enchantress Shalasar Glimmerdusk.\"" }
entries[210012] = { ["name"] = "Erden's Symbiotic Glowspore Grip", ["text"] = "Binds when picked up\nUse: Attempt to bind the Symbiotic Glowspore Grip to Fyr'alath, taking between 10-25% of your maximum health as shadowflame damage every second for 10 sec. (30 Sec Cooldown)\n\"An untested Glowspore Grip.\"" }
entries[210014] = { ["name"] = "Mysterious Ageless Seeds", ["text"] = "Quest Item\nUnique (20)\nUse: Plant a seed of the appropriate size at a nearby patch of Dreamseed Soil.\n\"Dreamseeds waiting to be awakened.\"" }
entries[210016] = { ["name"] = "Somnowl's Shroud", ["text"] = "Quest Item\nUnique\nUse: Enter stealth. Entering combat and casting abilities will break the effect. Enemies will detect you if you are too close to them. (8 Sec Cooldown)\n\"Call upon somnowl Bodwin to give you a temporary stealth aura.\"" }
entries[210017] = { ["name"] = "Fungal Fish", ["text"] = "Fungal Folly\n\"One Tusk claims this is a fish, but it really just looks like a partially eaten mushroom.\"" }
entries[210020] = { ["name"] = "Thundering Stormrider's Grips", ["text"] = "Cosmetic\nBinds to Warband\nHands Cosmetic\nUse: Add this appearance to your Warband collection." }
entries[210021] = { ["name"] = "Thundering Stormrider's Breastplate", ["text"] = "Cosmetic\nBinds to Warband\nChest Cosmetic\nUse: Add this appearance to your Warband collection." }
entries[210022] = { ["name"] = "Mimiron's Jumpjets", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Created as a prototype by Mimiron. The pieces were stolen from his workshop, sold, and lost to time. That is until now..\"\nWorld Event:\nSecrets of Azeroth" }
entries[210023] = { ["name"] = "Scrap of Parchment", ["text"] = "Quest Item\n\"A note that might shed light on how the Prophet of the Flame is blocking our reinforcements.\"" }
entries[210024] = { ["name"] = "Ensemble: Temporal Burdens", ["text"] = "Binds when picked up\nUse: Collect the shoulder armor appearances that Chromie and Morchie use.\n\"Emblems of the infinite and bronze dragonflights, suitable for wearing on one's shoulders.\"" }
