entries[210041] = { ["name"] = "Shipment of Goods", ["text"] = "Binds when picked up\nUnique (5)\n\"A box of useful goods prepared for the Dream Wardens with the assistance of Vashonir. Eran'nda will gladly accept these supply shipments.\"" }
