entries[210048] = { ["name"] = "Shalasar's Sophic Vellum", ["text"] = "Binds when picked up\nUse: Attempt to enchant Fyr'alath with Shalasar's Sophic Vellum. The enchantment will not work, but might help concentrate the Order magic to a usable state. (5 Min Cooldown)\n\"Crafted in tandem with Shalasar Glimmerdusk. Ready to be attuned to Fyr'alath.\"" }
entries[210049] = { ["name"] = "The Legend of Elun'Ahir", ["text"] = "Binds when picked up\nUnique\n\"As is common with ancient myths, details of this tale are oft disputed.\"\n<Right Click to Read>\nSell Price:" }
