entries[210057] = { ["name"] = "Reins of the Morning Flourish Dreamsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n\"Known for the lavish energy that emanates from them, these sabers are notorious tricksters. Their roar scatters the early birds that wake them.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1" }
entries[210058] = { ["name"] = "Reins of the Evening Sun Dreamsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n\"These dreamsabers are ferocious in battle, yet lethargic and often found lazily outstretched upon open fields. After soaking in the warmth of daylight, their flame flares that much brighter.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1" }
entries[210059] = { ["name"] = "Reins of the Winter Night Dreamsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"These nocturnal dreamsabers carry the chill of winter with them and will often hibernate for days on end if not otherwise awoken.\"\nDrop:\nDreamseed Cache\nZone:\nEmerald Dream" }
entries[210060] = { ["name"] = "Reins of the Shadow Dusk Dreamsaber", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"A dreamsaber strikes quickly from the shadows, capturing small animals and slipping back into darkness without a sound. The lucky few who have seen a feeding dreamsaber can see them revel in lazily toying with their prey before beginning their meal.\"\nAchievement:\nGlory of the Dream Raider\nCategory:\nDungeons & Raids" }
entries[210061] = { ["name"] = "Reins of Anu'relos, Flame's Guidance", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses Anu'relos, Flame's Guidance.\n\nThis mount can use Ride Along.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Though her feathers flicker with flame's destructive potential, they do not scorch, but simply radiate a comfortable heat.\"\nDrop:\nFyrakk\nZone:\nAmirdrassil, the Dream's Hope (Mythic)" }
