entries[210167] = { ["name"] = "Empyrium Filament", ["text"] = "Quest Item\n\"A thin, iridescent wire coveted by artificers for use in high-temp soldering.\"" }
entries[210168] = { ["name"] = "Hyperthermal Soldering Tool", ["text"] = "Quest Item\n\"A slender shard of thermocrystal able to heat itself to extremely precise temperatures.\"" }
entries[210169] = { ["name"] = "Pattern: Verdant Conduit", ["text"] = "Use: Teaches you how to craft Verdant Conduits.\nRequires Dragon Isles Leatherworking (50)\nSell Price:" }
entries[210170] = { ["name"] = "Design: Dreamtender's Charm", ["text"] = "Use: Teaches you how to craft Dreamtender's Charms.\nRequires Dragon Isles Jewelcrafting (35)\nSell Price:" }
entries[210171] = { ["name"] = "Formula: Enchanted Aspect's Dreaming Crest", ["text"] = "Binds when picked up\nUse: Teaches you how to create Enchanted Aspect's Dreaming Crests.\nRequires Dragon Isles Enchanting (50)\nSell Price:" }
entries[210172] = { ["name"] = "Formula: Enchanted Wyrm's Dreaming Crest", ["text"] = "Binds when picked up\nUse: Teaches you how to create Enchanted Wyrm's Dreaming Crests.\nRequires Dragon Isles Enchanting (45)\nSell Price:" }
entries[210173] = { ["name"] = "Formula: Enchanted Whelpling's Dreaming Crest", ["text"] = "Binds when picked up\nUse: Teaches you how to create Enchanted Whelpling's Dreaming Crest.\nRequires Dragon Isles Enchanting (35)\nSell Price:" }
entries[210174] = { ["name"] = "Formula: Illusory Adornment: Dreams", ["text"] = "Binds when picked up\nUse: Teaches you how to perform the Illusory Adornment: Dreams enchantment.\nTemporarily imbues shoulders with an illusion of the Dream for [source value] cd.\nRequires Dragon Isles Enchanting (25)\nSell Price:", ["unresolvedValues"] = true }
entries[210175] = { ["name"] = "Formula: Enchant Weapon - Dreaming Devotion", ["text"] = "Use: Teaches you how to perform the Dreaming Devotion enchantment.\nPermanently enchants a weapon to sometimes channel the power of the Dream. Your helpful spells may cause a magical flower to bloom near your target, healing nearby allies for 14168. Cannot be applied to items lower than level 180.\nRequires Dragon Isles Enchanting (50)\nSell Price:" }
entries[210176] = { ["name"] = "Q'onzu's Vision Charm", ["text"] = "Quest Item\nUse: Empowers you to detect Cinder-Charged wildlife within 40 yards in the Meandering Rootlands. (5 Sec Cooldown)" }
entries[210180] = { ["name"] = "Emerald Flightstone", ["text"] = "Binds when picked up\n\"Contains 100 Flightstones.\"\n<Right Click to Open>" }
entries[210181] = { ["name"] = "Signed Work Orders", ["text"] = "Quest Item\n\"A long list of artificing materials owed to Ataanya, stamped by Crystalsmith Laharu.\"" }
entries[210184] = { ["name"] = "Half-Filled Dreamless Sleep Potion", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Alchemy Knowledge by 3.\nRequires Dragon Isles Alchemy (25)\n\"In here, it is much easier to simply call it \"water\".\"" }
entries[210185] = { ["name"] = "Splash Potion of Narcolepsy", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Alchemy Knowledge by 3.\nRequires Dragon Isles Alchemy (25)\n\"Given the apparent goal of putting an enemy to sleep, it seems counterintuitive to douse them in the process.\"" }
entries[210189] = { ["name"] = "Exarch Hataaru's Artificing Lens", ["text"] = "Quest Item\n\"A small golden lens, worn with age and use. The precisely-carved facets allow artificers to see the energy channels running through the crystals used in their work.\"" }
entries[210190] = { ["name"] = "Blazeroot", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Alchemy Knowledge by 3.\nRequires Dragon Isles Alchemy (25)\n\"Smoldering to the touch. It would make for a fantastic catalyst for your concoctions, but good luck convincing any herbalist to play with fire.\"" }
entries[210193] = { ["name"] = "Experimental Dreamcatcher", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Engineering Knowledge by 3.\nRequires Dragon Isles Engineering (25)\n\"Bringing a magnet into the Emerald Dream does not inherently make it a dreamcatcher, but someone had to try it.\"" }
entries[210194] = { ["name"] = "Insomniotron", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Engineering Knowledge by 3.\nRequires Dragon Isles Engineering (25)\n\"A carefully calibrated device which emits a high-pitched sound only audible to sleeping druids.\"" }
entries[210197] = { ["name"] = "Unhatched Battery", ["text"] = "Binds when picked up\nDuration: 3 days\nUse: Study to increase your Dragon Isles Engineering Knowledge by 3.\nRequires Dragon Isles Engineering (25)\n\"Although seemingly mistaken for a misplaced egg, one might wonder what might have emerged if its incubation had not been interrupted.\"" }
entries[210198] = { ["name"] = "Depleted Battery", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Engineering Knowledge by 3.\nRequires Dragon Isles Engineering (25)\n\"What were you expecting, anyway?\"" }
entries[210199] = { ["name"] = "Tattered Dreamleaf", ["text"] = "Binds when picked up\nUse: Share the Tattered Dreamleaf with friendly party member allowing them to assist you in finding more Shadowed Dreamleaf.\n\"Remnant of a Shadowed Dreamleaf.\"" }
entries[210200] = { ["name"] = "Petrified Hope", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Jewelcrafting Knowledge by 3.\nRequires Dragon Isles Jewelcrafting (25)\n\"A pristine gemstone born from the husk of a thoroughly desecrated tree.\"" }
entries[210201] = { ["name"] = "Handful of Tiny Pebbles", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Jewelcrafting Knowledge by 3.\nRequires Dragon Isles Jewelcrafting (25)\n\"Ordinary rocks, significant only to you as a memoire to the time you scraped a few rocks off of a statue.\"" }
entries[210202] = { ["name"] = "Coalesced Dreamstone", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Jewelcrafting Knowledge by 3.\nRequires Dragon Isles Jewelcrafting (25)\n\"An incredible feat of gemcutting that bears a striking resemblance to your own lauded handiwork. How did it end up here?\"" }
