entries[210204] = { ["name"] = "Fading Flame Wristbands", ["text"] = "Binds when picked up\nWrist Cloth\n257 Armor\n+337 Intellect\n+1,197 Stamina\n+ 151 Haste\n+ 334 Mastery\nDurability 55 / 55\nSell Price:" }
entries[210205] = { ["name"] = "Vigilant Protector's Bracers", ["text"] = "Binds when picked up\nWrist Plate\n977 Armor\n+337 [Strength or Intellect]\n+1,197 Stamina\n+ 156 Versatility\n+ 329 Mastery\nDurability 55 / 55\nSell Price:" }
entries[210206] = { ["name"] = "Verdant Sanctuary Bands", ["text"] = "Binds when picked up\nWrist Leather\n440 Armor\n+337 [Agility or Intellect]\n+1,197 Stamina\n+ 335 Critical Strike\n+ 150 Haste\nDurability 55 / 55\nSell Price:" }
entries[210207] = { ["name"] = "Empowered Restorative Symbiote", ["text"] = "Quest Item\n\"The Glowspore Symbiotes grow stronger.\"" }
entries[210208] = { ["name"] = "Tuft of Dreamsaber Fur", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Leatherworking Knowledge by 3.\nRequires Dragon Isles Leatherworking (25)\n\"While too small a sample to do anything with, this dreamsaber fur is a fascinating material to study the properties of.\"" }
entries[210211] = { ["name"] = "Molted Faerie Dragon Scales", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Leatherworking Knowledge by 3.\nRequires Dragon Isles Leatherworking (25)\n\"Shimmering and iridescent, these scales could be used in decorative armor. However, they likely wouldn't stand up well to combat.\"" }
entries[210214] = { ["name"] = "Ouroboreal Necklet", ["text"] = "Binds when picked up\nNeck\n+1,197 Stamina\n+ 360 Critical Strike\n+ 1,442 Versatility\nEquip: Dealing Fire damage grants you a shield absorbing 56615 Nature damage. Dealing Nature damage grants you a shield absorbing 56615 Fire damage. This effect may only occur every 1 min. (1m cooldown)\nSell Price:" }
entries[210215] = { ["name"] = "Dreamtalon Claw", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Leatherworking Knowledge by 3.\nRequires Dragon Isles Leatherworking (25)\n\"Extremely sharp, remarkably durable, and still in fantastic condition! There is a little tree bark stuck to it, though.\"" }
entries[210217] = { ["name"] = "Small Dreamy Bounty", ["text"] = "Binds when picked up\n\"Contains a unique cosmetic or a small amount of profession reagents.\"\n<Right Click to Open>" }
entries[210218] = { ["name"] = "Plump Dreamy Bounty", ["text"] = "Binds when picked up\n\"Contains a unique battle pet or a medium amount of profession reagents.\"\n<Right Click to Open>" }
entries[210219] = { ["name"] = "Gigantic Dreamy Bounty", ["text"] = "Binds when picked up\n\"Contains a unique mount or a large amount of profession reagents.\"\n<Right Click to Open>" }
entries[210220] = { ["name"] = "Resilient Mask", ["text"] = "Binds when equipped\nHead Leather\n241 Armor\n+216 [Agility or Intellect]\n+323 Stamina\n+ 204 Versatility\nSell Price:" }
entries[210221] = { ["name"] = "Forged Combatant's Heraldry", ["text"] = "The War Within Season 1\nOptional Crafting Reagent\n\n\"Acquired from various PvP activities or purchased with Honor from PvP quartermasters in Dornogal. Can be bought and sold on the Auction House.\"" }
entries[210222] = { ["name"] = "Resolved Element", ["text"] = "Quest Item\n\"A quelled element capable of being rebound to the Concentrated Sophic Vellum.\"" }
entries[210223] = { ["name"] = "Unstable Element", ["text"] = "Binds when picked up\nUse: Return the Stabilized Element to the wielder of Fyr'alath.\n\"An element still needing to be stabilized.\"\nSell Price:" }
entries[210224] = { ["name"] = "Small Emerald Bloom", ["text"] = "Binds when picked up\n\"Contains a small amount of Dragon Isles Supplies and Flightstones. Includes a minute chance to get the Winter Night Dreamsaber mount.\"\n<Right Click to Open>" }
